STATE_ABBR2NAME = {ab: nm.title() for nm, ab in STATE_NAME2ABBR.items()}
STATE_ABBR2NAME["dc"] = "District of Columbia"      # title() 会把 of 大写, 修正回习惯写法


def haversine_km(lat1, lon1, lat2, lon2):
    R = 6371.0
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dp = math.radians(lat2 - lat1)
    dl = math.radians(lon2 - lon1)
    a = math.sin(dp / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dl / 2) ** 2
    return 2 * R * math.asin(math.sqrt(max(0.0, min(1.0, a))))


def distance_to_hubs(lat, lon):
    """返回 (最近的hub名, 距离km)"""
    best = (None, 1e9)
    for name, (hla, hlo) in HUBS.items():
        d = haversine_km(lat, lon, hla, hlo)
        if d < best[1]:
            best = (name, d)
    return best


def _norm(s):
    return re.sub(r"\s+", " ", (s or "").strip())


def lookup(loc_text, state_hint=""):
    """位置文本 -> 坐标。返回 (lat, lon, confidence, matched)

    confidence: city(精确) / state(州中心兜底, 低置信) / none(认不出)
    严格匹配, 不做模糊包含查找。
    """
    raw = _norm(loc_text)
    if not raw:
        return None, None, "none", ""
    parts = [p.strip() for p in re.split(r"[,，]", raw) if p.strip()]
    city_part = parts[0].lower() if parts else ""
    region_part = parts[1].lower().replace(".", "").strip() if len(parts) > 1 else ""

    # 识别州
    st = ""
    sh = _norm(state_hint).lower().replace(".", "")
    if sh in STATE_XY:
        st = sh
    elif sh in STATE_NAME2ABBR:
        st = STATE_NAME2ABBR[sh]
    if not st and region_part:
        if region_part in STATE_XY:
            st = region_part
        elif region_part in STATE_NAME2ABBR:
            st = STATE_NAME2ABBR[region_part]
    if not st:
        for p2 in parts[1:]:
            lp = p2.lower().replace(".", "").strip()
            if lp in STATE_XY:
                st = lp
                break
            if lp in STATE_NAME2ABBR:
                st = STATE_NAME2ABBR[lp]
                break

    # 城市精确匹配(先带州, 再不带州)
    cands = []
    if city_part and st:
        cands.append(f"{city_part}|{st}")
    cands.append(city_part)
    for k in cands:
        if k and k in CITY_XY:
            la, lo, _ = CITY_XY[k]
            return la, lo, "city", k
    # 多段情况: 逐段试
    for p2 in parts[:-1] if len(parts) > 2 else []:
        lp = p2.lower()
        if lp in CITY_XY:
            la, lo, _ = CITY_XY[lp]
            return la, lo, "city", lp

    # ★ 2026-09-18 新增: 整段文本本身就是州名/州缩写(如 "IL" / "N.Y." / "Illinois")
    #   -> 记为州级判定走下面的州兜底; 以前这种情况会直接返回 "认不出"
    #   (只在城市精确匹配失败之后才走这里, 不会影响 "New York" 这类同名城市的命中)
    if not st:
        cp = city_part.replace(".", "").strip()
        if cp in STATE_XY:
            st = cp
        elif cp in STATE_NAME2ABBR:
            st = STATE_NAME2ABBR[cp]

    # 州兜底
    if st and st in STATE_XY:
        la, lo = STATE_XY[st]
        return la, lo, "state", st
    return None, None, "none", ""


def state_center(abbr_or_name):
    """★ 新增: 州缩写('ny'/'NY'/'N.Y.')或全名('New York'/'new york') -> (lat, lon, 州全名)

    认不出返回 None。只用州级数据, 不涉及城市。
    """
    s = _norm(abbr_or_name).lower().replace(".", "")
    if not s:
        return None
    ab = s if s in STATE_XY else STATE_NAME2ABBR.get(s)
    if not ab or ab not in STATE_XY:
        return None
    la, lo = STATE_XY[ab]
    return la, lo, STATE_ABBR2NAME.get(ab, ab.upper())


def is_new_york(text):
    """★ 新增: 判断一段地名/州名文本是不是纽约州。

    接受: 'New York' / 'NY' / 'ny' / 'New York, NY' / '纽约' / 'NYC' / 'New York City' 等。
    做法: 按逗号分段, 每段做"整段严格相等"比较(不做子串模糊匹配, 避免误伤
          'Manhattan, KS' 这类同名异地)。
    """
    s = _norm(text)
    if not s:
        return False
    if "纽约" in s:                       # 中文写法(含 "纽约市"/"纽约州")
        return True
    parts = [p.strip().lower().replace(".", "") for p in re.split(r"[,，]", s) if p.strip()]
    return any(p in ("ny", "new york", "new york city", "nyc") for p in parts)


def states_in_band(center_lat, center_lon, min_km=None, max_km=None):
    """★ 新增: 圆心(某号所在地)周边"州中心落在环带内"的州列表, 按距离升序。

    返回 [(州缩写小写, 州全名, 距离km), ...]
    用途: 自动决定该号需要扫哪些州的路段(州中心是粗判, 只用于挑选, 不用于淘汰人)。
    """
    mn = BAND_MIN_KM if min_km is None else float(min_km)
    mx = BAND_MAX_KM if max_km is None else float(max_km)
    out = []
    for ab, (la, lo) in STATE_XY.items():
        d = haversine_km(center_lat, center_lon, la, lo)
        if mn <= d <= mx:
            out.append((ab, STATE_ABBR2NAME.get(ab, ab.upper()), d))
    out.sort(key=lambda r: r[2])
    return out


def resolve_center(loc_text, state_hint=""):
    """★ 新增: 号自己在 Strava 上的所在地文本 -> 环带圆心。返回 (lat, lon, label, conf)

    conf = "city"  城市级精确命中: lat/lon 为该城市坐标, label 用人类可读的原文本
           "state" 只认到州: lat/lon 为该州中心(仅供挑选要扫的州, in_target_band 不据此淘汰)
           "none"  认不出  : (None, None, "", "none")  -> 调用方应保持"不误杀"
    """
    la, lo, conf, matched = lookup(loc_text, state_hint)
    if conf == "city" and la is not None:
        return la, lo, (_norm(loc_text) or str(matched)), "city"
    if conf == "state":
        sc = state_center(matched) or state_center(state_hint)
        if sc:
            return sc[0], sc[1], sc[2], "state"
        if la is not None:
            return la, lo, str(matched).upper(), "state"
    return None, None, "", "none"


def _unpack_center(center):
    """★ 新增(内部): 圆心参数归一化 -> (lat, lon, label)

    兼容 (lat, lon) / (lat, lon, label) / {"lat":..,"lon":..,"label":..}; 取不到坐标返回 (None, None, "")
    """
    if isinstance(center, dict):
        clat, clon = center.get("lat"), center.get("lon")
        if clat is None or clon is None:
            return None, None, ""
        clat, clon = float(clat), float(clon)
        clabel = center.get("label") or f"{clat:.4f},{clon:.4f}"
        return clat, clon, str(clabel)
    vals = list(center)
    if len(vals) < 2 or vals[0] is None or vals[1] is None:
        return None, None, ""
    clat, clon = float(vals[0]), float(vals[1])
    clabel = str(vals[2]) if len(vals) > 2 and vals[2] else f"{clat:.4f},{clon:.4f}"
    return clat, clon, clabel


def in_target_band(loc_text, state_hint="", min_km=None, max_km=None,
                   center=None, exempt_max=False):
    """判定是否落在目标环带内。

    返回 (ok, reason, confidence, dist_km, center_label)   ← 仍是 5 元组, 顺序与旧版一致
      ok = True  保留
      ok = False 淘汰(只在 city 高置信度判定时给出)
      ok = None  无法确定的低置信情况 -> 调用方保留(不误杀)

    ★ 2026-09-18 第2条口径:
      center=(lat, lon, label)  圆心 = 该号自己在 Strava 上的所在地
                                (引擎先用 resolve_center() 求出, 再传进来)
      center=None              沿用老行为: 取 HUBS 里离目标最近的那个做圆心(向后兼容)
      min_km / max_km          默认 BAND_MIN_KM / BAND_MAX_KM (100 / 1000)
      exempt_max=True          纽约州路段来源: 只判"太近", 超上限一律通过
                               (理由里明确写出"★纽约来源豁免上限")
    """
    mn = BAND_MIN_KM if min_km is None else float(min_km)
    mx = BAND_MAX_KM if max_km is None else float(max_km)

    la, lo, conf, matched = lookup(loc_text, state_hint)
    if conf == "none" or la is None:
        return None, f"位置无法识别({loc_text or '空'})", "none", None, None

    # ---- 圆心: 传了就用传进来的(该号所在地), 没传就沿用老逻辑(最近的 HUBS)
    clat = clon = None
    clabel = ""
    if center is not None:
        try:
            clat, clon, clabel = _unpack_center(center)
        except (TypeError, ValueError):
            clat = clon = None
    if clat is None or clon is None:
        hub, _ = distance_to_hubs(la, lo)
        clat, clon = HUBS[hub]
        clabel = hub

    d = haversine_km(la, lo, clat, clon)

    if conf == "state":
        # 州中心不代表具体城市, 不做淘汰(传了 center 也一样)
        tail = "(★纽约来源豁免上限, 但州级粗判仍不淘汰)" if exempt_max else ""
        return None, f"州级粗判距{clabel}{d:.0f}km, 无法确定{tail}", conf, d, clabel
    if d < mn:
        return False, f"距{clabel}仅{d:.0f}km(<{mn:.0f} 太近)", conf, d, clabel
    if d > mx:
        if exempt_max:
            # ★ 纽约州路段采到的人豁免 1000km 上限, 但仍受上面的 >100km 约束
            return True, f"距{clabel}{d:.0f}km(超{mx:.0f}, ★纽约来源豁免上限, 通过)", conf, d, clabel
        return False, f"距{clabel}{d:.0f}km(>{mx:.0f} 太远)", conf, d, clabel
    return True, f"距{clabel}{d:.0f}km(环带内)", conf, d, clabel


if __name__ == "__main__":
    def _mark(ok):
        return {True: "保留", False: "淘汰", None: "不确定"}[ok]

    def _w(s):
        """显示宽度(中文/★等宽字符按 2 列算), 只为表格对齐"""
        n = 0
        for ch in str(s):
            o = ord(ch)
            wide = (0x1100 <= o <= 0x115F or 0x2E80 <= o <= 0xA4CF or 0xAC00 <= o <= 0xD7A3
                    or 0xF900 <= o <= 0xFAFF or 0xFE30 <= o <= 0xFE6F or 0xFF00 <= o <= 0xFF60
                    or 0xFFE0 <= o <= 0xFFE6 or o == 0x2605)
            n += 2 if wide else 1
        return n

    def _pad(s, width):
        return str(s) + " " * max(1, width - _w(s))

    print("=" * 150)
    print(f"★ 新口径自测: 环带 = 距【该号自己在 Strava 上的所在地】"
          f"{BAND_MIN_KM:.0f}~{BAND_MAX_KM:.0f}km; 纽约州来源豁免上限(但仍须 >{BAND_MIN_KM:.0f}km)")
    print("=" * 150)

    # ---- 第1步: 每个号自己的所在地 -> 圆心(模拟引擎"识别该号所在地"这一步)
    centers = {}
    for ct in ("Chicago, IL", "Los Angeles, CA"):
        lat, lon, label, conf = resolve_center(ct)
        centers[ct] = (lat, lon, label)
        print(f"  resolve_center({ct!r}) -> ({lat}, {lon}, {label!r}, {conf!r})")
    print()

    # ---- 第2步: 用该号自己的圆心判人
    cases = [
        # (圆心=该号所在地, 目标地名, state_hint, exempt_max(纽约来源), 期望)
        ("Chicago, IL", "Chicago, IL", "", False, "淘汰(0km 太近)"),
        ("Chicago, IL", "Milwaukee, Wisconsin", "", False, "保留(~131km)"),
        ("Chicago, IL", "Buffalo, NY", "", False, "保留(~727km 直线)"),
        ("Chicago, IL", "New York, NY", "", False, "淘汰(~1140km >1000)"),
        ("Chicago, IL", "New York, NY", "", True, "★保留(纽约来源豁免上限)"),
        ("Chicago, IL", "", "", False, "不确定(空地名)"),
        ("Chicago, IL", "Nowhereville, ZZ", "", False, "不确定(认不出)"),
        ("Chicago, IL", "IL", "", False, "不确定(只给州->州级粗判)"),
        ("Chicago, IL", "Nowhereville", "IL", False, "不确定(州级粗判)"),
        ("Los Angeles, CA", "Los Angeles, CA", "", False, "淘汰(0km 太近)"),
        ("Los Angeles, CA", "New York, NY", "", False, "淘汰(~3940km >1000)"),
        ("Los Angeles, CA", "New York, NY", "", True, "★保留(纽约来源豁免上限)"),
        ("Los Angeles, CA", "Pasadena, CA", "", False, "淘汰(~14km 太近)"),
        ("Los Angeles, CA", "Pasadena, CA", "", True, "淘汰(豁免也救不了 <100km)"),
    ]

    print(_pad("圆心(该号所在地)", 18) + _pad("目标", 22) + _pad("豁免", 6) + _pad("置信", 7)
          + _pad("距离km", 10) + _pad("判定", 8) + _pad("期望", 30) + "原因")
    print("-" * 150)
    for ctext, target, hint, exempt, expect in cases:
        clat, clon, clabel = centers[ctext]
        ok, why, conf, d, lbl = in_target_band(target, hint, center=(clat, clon, clabel),
                                               exempt_max=exempt)
        print(_pad(clabel, 18) + _pad(target or "(空)", 22) + _pad("是" if exempt else "否", 6)
              + _pad(conf, 7) + _pad(f"{d:.0f}" if d is not None else "-", 10)
              + _pad(_mark(ok), 8) + _pad(expect, 30) + why)

    # ---- 向后兼容: 不传 center = 老行为(取 HUBS 里离目标最近的那个做圆心)
    print()
    print("向后兼容 center=None (老行为: 取 HUBS 里最近者做圆心, 旧调用方不受影响):")
    for t in ("Chicago, IL", "Milwaukee, Wisconsin", "New York, NY", "Los Angeles, CA"):
        ok, why, conf, d, lbl = in_target_band(t)
        print("  " + _pad(f"in_target_band({t!r})", 42) + _pad(_mark(ok), 8)
              + _pad(f"conf={conf}", 12) + f"圆心={lbl}  {why}")

    # ---- 辅助接口
    print()
    print("辅助接口:")
    for s in ("ny", "NY", "New York", "N.Y.", "illinois", "ZZ"):
        print("  " + _pad(f"state_center({s!r})", 30) + f"-> {state_center(s)}")
    for t in ("New York", "NY", "ny", "New York, NY", "New York City", "纽约",
              "Buffalo, NY", "Manhattan, KS", "Newark, NJ", ""):
        print("  " + _pad(f"is_new_york({t!r})", 30) + f"-> {is_new_york(t)}")

    # ---- 自动选州: 前 15 个
    print()
    clat, clon = HUBS["Chicago"]
    rows = states_in_band(clat, clon)
    print(f"states_in_band(芝加哥) -> 共 {len(rows)} 个州(州中心落在 "
          f"{BAND_MIN_KM:.0f}~{BAND_MAX_KM:.0f}km 内), 前 15 个 (缩写, 州全名, 州中心距圆心 km):")
    for ab, nm, d in rows[:15]:
        print("  " + _pad(ab, 6) + _pad(nm, 26) + f"{d:>8.1f}")
